describe('sumUsage', () => {
  it('adds each token field of two reported rounds', () => {
    const first: UsageMetadata = {inputTokens: 2, outputTokens: 1, totalTokens: 3};
    const second: UsageMetadata = {inputTokens: 7, outputTokens: 4, totalTokens: 11};

    expect(sumUsage(first, second)).toEqual({inputTokens: 9, outputTokens: 5, totalTokens: 14});
  });

  it('keeps the reported side when the other round reported nothing', () => {
    const reported: UsageMetadata = {inputTokens: 2, outputTokens: 1, totalTokens: 3};

    expect(sumUsage(undefined, reported)).toEqual(reported);
    expect(sumUsage(reported, undefined)).toEqual(reported);
  });

  it('stays undefined when no round reported usage', () => {
    expect(sumUsage(undefined, undefined)).toBeUndefined();
  });
});
EOF
